// Kysely type definitions for cobblr_meta. Mirror the SQL in
// migrations/platform/*.sql.
//
// New table → add a new interface here + Kysely will give you typed
// queries automatically. If a column is generated by Postgres (uuid
// default, timestamptz default) wrap it with Generated<...> so insert
// types don't require you to supply it.

import type { ColumnType, Generated } from "kysely";
import type { OrgRoleName } from "@cobblr/platform-contract/org-roles";
// Type-only: the card's one definition lives with the channels that render it.
import type { NotificationCard } from "../platform/channels/types.js";

export interface UsersTable {
  id: Generated<string>;
  email: string;
  password_hash: string;
  display_name: string;
  active: Generated<boolean>;
  /** Per-user theme preference: "light" | "dark" | null (follow device/OS).
   *  Follows the user across devices + workspaces; never touches a workspace's
   *  own skin or another member's view. */
  theme_pref: "light" | "dark" | null;
  /** Desktop nav layout that follows the user across devices. null = the device
   *  default stands. A phone ignores it: the sidebar renders `hidden md:block`. */
  nav_pref: { mode: "top" | "side"; autohide: boolean; topbar: boolean } | null;
  /** When the guided tour was completed or skipped. NULL = never. Lives on the
   *  ACCOUNT because localStorage forgets on a new device, a different origin
   *  (the main host vs a preview host) and a cleared cache. */
  tour_seen_at: Date | null;
  /** True when an admin minted this account with a temp password.
   *  Login succeeds; the response carries the flag and the web
   *  client renders the set-a-password screen IN PLACE OF every route
   *  until the user picks their own. Not a URL: a gate, so there is
   *  nothing to navigate around. PATCH /me/password clears it. */
  must_reset_password: Generated<boolean>;
  /** uuid of the admin who minted the account (null = self-signup). */
  created_by: string | null;
  /** When the user confirmed their email via a verification link. NULL =
   *  unverified. Existing users were grandfathered to created_at by the
   *  20260606-043 migration. Informational today (login is not gated on it). */
  email_verified_at: Date | null;
  created_at: Generated<Date>;
  last_login_at: Date | null;
  /** Session-revocation cutoff. A session/app JWT whose `iat` is before this
   *  is rejected by requireAuth. Set to now() on password change/reset. NULL =
   *  no tokens invalidated yet. */
  tokens_valid_from: Date | null;
  /** Slice 3 (central identity): this local user's global identity id, set by the
   *  backfill reconcile once IDENTITY_URL is wired. A verified central token's `sub`
   *  maps to this row through this column. NULL = not yet linked (or identity off). */
  identity_id: string | null;
}

export interface OrgsTable {
  id: Generated<string>;
  name: string;
  slug: string;
  db_name: string;
  db_credentials_encrypted: string | null;
  plan: Generated<"free" | "paid" | "disabled">;
  /** Per-workspace AI opt-out. When true, the workspace/managed AI default is
   *  off here; a user's own personal connection still works. */
  ai_disabled: Generated<boolean>;
  /** Member-portal config — branding + pinned views shown in the
   *  slimmed-down `/portal/:slug` shell. See
   *  docs/modules/member-portal-and-permissions.md. */
  portal_config: Generated<{
    display_name?: string;
    logo_path?: string | null;
    theme?: "light" | "dark" | "auto";
    pinned_views: string[];
    welcome_markdown?: string;
  }>;
  /** Admin dashboard arrangement — order + visibility (+ tile width) of the
   *  home "at a glance" tiles AND the order + visibility of the whole sections
   *  (at-a-glance / pinned views / recent activity). Null = default order, all
   *  visible. Widget + section ids are owned by the web layer; this column only
   *  stores their order, a hidden flag, and an optional tile column-span. */
  dashboard_layout: Generated<{
    widgets: { id: string; hidden: boolean; span?: number }[];
    sections?: { id: string; hidden: boolean }[];
  } | null>;
  /** Managed vertical-app config — when set, this workspace is a single-purpose
   *  "managed app" ("Cobblr for Yarn"): the web hides all platform chrome and
   *  lands the user straight in the app. NULL = normal platform workspace.
   *  See business-models/docs/18-managed-vertical-apps.md. */
  app_mode: Generated<{
    /** App id, e.g. "yarn" — keys the managed-app registry. */
    app: string;
    /** Route to land in inside the app, e.g. "/inventory". */
    home_path: string;
    /** Display label, e.g. "Cobblr for Yarn". */
    label?: string;
  } | null>;
  /** Focused mode — when true, the web shell hides the platform BUILDER chrome
   *  (marketplace / add-modules / AI builder / Configuration / the "+ New thing"
   *  funnel) so a non-technical owner sees a finished app, not a toolkit. Softer
   *  than app_mode (workspace stays navigable; owner can flip it back, which is
   *  the upsell). false = full platform (the default). */
  focused: Generated<boolean>;
  /** try/trial tier: when set, this workspace is a trial that expires at this
   *  time. Reaping is deferred — the stamp is set at signup but nothing sweeps
   *  yet. NULL = a normal workspace (every non-`try` instance). See
   *  docs/design-decisions/try-instance.md. */
  trial_expires_at: Generated<Date | null>;
  /** try/trial tier: when the humane reaper sent this workspace its "trial ends
   *  soon" warning email. NULL = never warned. The reaper's warn -> grace ->
   *  delete lifecycle only deletes a workspace warned at least `grace` days ago,
   *  so an un-warned trial can never be silently reaped. See
   *  platform/reap-trials.ts. */
  trial_expiry_warned_at: Generated<Date | null>;
  /** Slice 4 (demo workspaces): per-workspace entitlement overrides — an allow-list of
   *  feature keys ("files.upload", "workspaces.create") and module names ("core-ai") the
   *  trial guard + module-enable gate honour for THIS workspace, so an operator-provisioned
   *  demo can use what real trials can't. Empty everywhere else. */
  demo_unlocks: Generated<string[]>;
  created_at: Generated<Date>;
  updated_at: Generated<Date>;
  /** Handed out by GET /try — a one-hour sandbox, not an account trial. */
  sandbox: Generated<boolean>;

}

