// Re-exported, not redeclared: this union used to be a hand-written copy and
// had drifted from the others. Imported as well so it is in scope below.
import type { FieldDefType } from "@cobblr/platform-contract";
export type { FieldDefType };

export interface ModuleFieldDefsTable {
  id: Generated<string>;
  org_id: string;
  entity_kind: string;
  name: string;
  display_label: string;
  type: FieldDefType;
  required: Generated<boolean>;
  position: Generated<number>;
  bundle_id: string | null;
  /** Set when this row was contributed by a Pillar-E module's
   *  `contributes.fieldDefs`. Cleaned up on module disable. */
  source_module: string | null;
  /** When type='text', renders as a dropdown of these choices. The
   *  "+ add new" affordance in the UI PATCHes this array. */
  choices: string[] | null;
  /** Built-in renderer id for displaying this field's value in
   *  list rows + detail pages. Same fixed set as
   *  CatalogSchema.field_renderers — color-hex, image-url,
   *  url-link, year, boolean, code, or null (= plain text). */
  renderer: string | null;
  /** The unit a numeric value is measured in ("mm", "g", "in"). Free text
   *  by design — the units vocabulary (core-units) resolves it at
   *  render/consume time; unmatched strings render as-is. A unit that
   *  resolves to a catalog category gives the field declared physical
   *  semantics (length/mass/…) without keyword-matching its name. */
  unit: string | null;
  /** For type='computed': the {{ }} template rendered at entity-resolve
   *  time over the entity's own fields (tier 1) + registered context
   *  providers (tier 2). Null for stored value fields. */
  template: string | null;
  /** Plain-language one-line hint shown under the input on create + detail
   *  forms, so jargon fields (colorway, dye lot…) explain themselves. */
  help: string | null;
  /** Form-builder section this field belongs to (field_sections.id), or null
   *  for ungrouped. Set together with position by the reorder call. */
  section_id: string | null;
  /** Server-managed: the value is computed/stamped server-side (e.g.
   *  core-mobility's `away_since`) and a client write is never accepted — the
   *  write router preserves the stored value across an unrelated edit. */
  server_managed: Generated<boolean>;
  /** For type='relation': the entity-kind id this field references
   *  (e.g. "core-locations:location"). Null for non-relation defs. The stored
   *  VALUE (a target id) lives in the entity's metadata; the read layer resolves
   *  it to the target's title and injects `<name>_label`. */
  ref_kind: string | null;
  /** Semantic DECODE role (P3 of the identifier-decoder registry). Either
   *  `identifier:<decoderId>` (this field holds a decodable code) or
   *  `decode:<key>` (fill from the decoder's <key> output). Null for ordinary
   *  fields. See packages/platform-contract parseDecodeRole. */
  decode_role: string | null;
  /** Semantic role of the field IN THE RECORD — distinct from `decode_role`
   *  (identifier decoding) and from the manifest's presentation role (how to
   *  DISPLAY it). Today: `category` — the field saying what KIND of thing this
   *  record is, WITHIN its table. The scan matchmaker routes on it, so that a
   *  difference in kind is expressed as a CATEGORY rather than by scattering
   *  items across near-synonym tables. Declared, never guessed. At most one
   *  category field per (org, kind) — enforced by a partial unique index. */
  field_role: string | null;
  /** TRAIT SCOPE: when set, this def applies to a CLASS of entity kinds
   *  ("everything physical") rather than the single `entity_kind` it's keyed to,
   *  and `entity_kind` holds a scope sentinel (`@physical`) instead of a real
   *  kind. The value is an ActionAppliesToDecl — the same predicate the action
   *  registry matches — so one matcher serves both. Null = per-kind (the
   *  default). See platform/field-defs.ts + docs/design-decisions/trait-scoped-fields.md. */
  applies_to: unknown | null;
  created_at: Generated<Date>;
}

